    SELECT `CustomerID`
    FROM c_cols
    WHERE `Price` / `Amount` > 29.00 AND `Date` LIKE '2012-08%'
)
SELECT * FROM c_rows;

WITH final_result AS (
    SELECT `CustomerID`, `Consumption`
    FROM t_join
)
SELECT * FROM final_result;

WITH final_count AS (
    SELECT COUNT(DISTINCT `CustomerID`) AS answer
    FROM t_join
)
SELECT * FROM final_count;

WITH final_answer AS (
    SELECT `CustomerID`, `Consumption`
    FROM t_join
)
SELECT * FROM final_answer;

WITH final_output AS (
    SELECT `CustomerID`, `Consumption`
    FROM t_join
)
SELECT * FROM final_output;

WITH c_cols AS (
    SELECT e.event_id, e.event_name, e.event_date, e.type, e.notes, e.location, e.status, b.category, b.amount, b.link_to_event
    FROM event AS e
    LEFT JOIN budget AS b ON e.event_id = b.link_to_event
)
SELECT * FROM c_cols;

WITH c_agg AS (
    SELECT SUM(amount) AS total_parking_cost, COUNT(event_id) AS total_parking_events
    FROM c_rows
)
SELECT * FROM c_agg;

WITH c_avg AS (
    SELECT total_parking_cost / total_parking_events AS avg_parking_cost
    FROM c_agg
)
SELECT * FROM c_avg;

WITH c_final AS (
    SELECT e.event_name
    FROM c_rows e
    WHERE e.amount < 10
)
SELECT * FROM c_final;

WITH c_cols AS (
    SELECT e.event_id, e.event_name, e.event_date, e.type, e.notes, e.location, e.status, b.category, b.amount, b.link_to_event
    FROM event AS e
    LEFT JOIN budget AS b ON e.event_id = b.link_to_event
)
SELECT * FROM c_cols;

WITH avg_parking_cost AS (
    SELECT SUM(amount) / COUNT(event_id) AS avg_parking_cost
    FROM c_rows
)
SELECT * FROM avg_parking_cost;

WITH t_rows AS (
    SELECT event_name
    FROM c_rows
    WHERE amount < (SELECT avg_parking_cost FROM avg_parking_cost)
)
SELECT * FROM t_rows;

WITH c_cols AS (
    SELECT e.event_id, e.event_name, e.event_date, e.type, e.notes, e.location, e.status, b.category, b.amount, b.event_status
    FROM event AS e
    LEFT JOIN budget AS b ON e.event_id = b.link_to_event
)
SELECT * FROM c_cols;

WITH c_rows AS (
    SELECT event_id, event_name, category, amount
    FROM c_cols
    WHERE category = 'Parking'
)
SELECT * FROM c_rows;

WITH t_agg AS (
    SELECT AVG(amount) AS avg_parking_cost
    FROM c_rows
)
SELECT * FROM t_agg;

WITH t_rows AS (
    SELECT event_name
    FROM c_rows
    WHERE amount < 10.0
)
SELECT * FROM t_rows;

WITH c_cols AS (
    SELECT y.`Date`, y.`Consumption`
    FROM yearmonth AS y
)
SELECT * FROM c_cols;

WITH c_rows AS (
    SELECT `Date`, `Consumption`
    FROM c_cols
    WHERE `Date` IS NOT NULL AND `Consumption` IS NOT NULL
)
SELECT * FROM c_rows;

WITH t_date AS (
    SELECT SUBSTR(`Date`, 1, 4) AS `Year`, `Consumption`
    FROM t_join
)
SELECT * FROM t_date;

WITH t_agg AS (
    SELECT `Year`, SUM(`Consumption`) AS TotalConsumption
    FROM t_date
    GROUP BY `Year`
)
SELECT * FROM t_agg;

WITH c_cols AS (
    SELECT y.`Date`, y.`Consumption`
    FROM yearmonth AS y
)
SELECT * FROM c_cols;

WITH c_rows AS (
    SELECT `Date`, `Consumption`
    FROM c_cols
    WHERE `Date` IS NOT NULL AND `Consumption` IS NOT NULL
)
SELECT * FROM c_rows;

WITH t_date AS (
    SELECT SUBSTR(`Date`, 1, 4) AS `Year`, SUM(`Consumption`) AS `TotalConsumption`
    FROM c_rows
    GROUP BY SUBSTR(`Date`, 1, 4)
)
SELECT * FROM t_date;

WITH c_rows AS (
    SELECT Date, SUM(Consumption) AS TotalConsumption
    FROM c_cols
    GROUP BY Date
)
SELECT * FROM c_rows;

WITH t_date AS (
    SELECT Date, TotalConsumption
    FROM c_rows
    WHERE Date LIKE '2012%' OR Date LIKE '2013%'
)
SELECT * FROM t_date;

WITH t_year AS (
    SELECT STRFTIME('%Y', Date) AS Year, SUM(TotalConsumption) AS TotalConsumption
    FROM t_date
    GROUP BY STRFTIME('%Y', Date)
)
SELECT * FROM t_year;

WITH t_year_filtered AS (
    SELECT Year, TotalConsumption
    FROM t_year
    WHERE Year BETWEEN '2012' AND '2023'
)
SELECT * FROM t_year_filtered;

WITH fuzzy_year_match AS (
    SELECT Year, TotalConsumption
    FROM t_year
    WHERE Year LIKE '%2012%' OR Year LIKE '%2013%'
)
SELECT * FROM fuzzy_year_match;

WITH c_rows AS (
    SELECT Date, SUM(Consumption) AS TotalConsumption
    FROM c_cols
    GROUP BY Date
)
SELECT * FROM c_rows;

WITH t_date AS (
    SELECT STRFTIME('%Y', Date) AS Year, SUM(TotalConsumption) AS TotalConsumption
    FROM c_rows
    GROUP BY STRFTIME('%Y', Date)
)
SELECT * FROM t_date;
